<?php require __DIR__.'/../layout.php'; ?><section class="card"><div class="top"><h2>Daftar Kategori</h2><a class="btn" href="index.php?module=kategori&action=form">+ Tambah Kategori</a></div><table><thead><tr><th>ID</th><th>Nama</th><th>Aksi</th></tr></thead><tbody><?php foreach($items as $row): ?><tr><td><?= (int)$row['id'] ?></td><td><?= htmlspecialchars($row['nama']) ?></td><td><a href="index.php?module=kategori&action=form&id=<?= (int)$row['id'] ?>">Edit</a> <form class="inline" method="post" action="index.php?module=kategori&action=delete" onsubmit="return confirm('Hapus kategori ini?')"><input type="hidden" name="csrf" value="<?= htmlspecialchars($_SESSION['csrf']) ?>"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="link danger">Hapus</button></form></td></tr><?php endforeach; ?></tbody></table><?php if(!$items): ?><p>Belum ada kategori.</p><?php endif; ?></section></main></div></body></html>
